/**
 * Decide: turns learned patterns into suggestions.
 * Each rule only fires when there is enough data, and each suggestion carries a one-line
 * "why" built from the real numbers. Nothing here is generated by an LLM.
 */
import {
  MIN_DAYS_FOR_PREDICTION,
  predictOutageWindow,
  predictReturnHour,
  startOfLocalDay
} from './learn';
import {
  dayKey,
  durationLabel,
  hourLabel,
  naira,
  partOfDay,
  round1,
  shortBankName,
  timeLabel
} from './format';
import type { AgentContext, Insight, LearnedPatterns } from './types';

const HOUR = 3_600_000;
const iso = (d: Date) => d.toISOString();
const endOfDay = (now: Date) => new Date(startOfLocalDay(now).getTime() + 24 * HOUR - 1);

/** Best pump price we know of in the state, else the user's own gen price setting. */
function bestFuelPrice(ctx: AgentContext, p: LearnedPatterns): number {
  return p.fuel?.cheapest?.priceNgn || ctx.gen.fuelPricePerLitreNgn;
}

export function buildInsights(ctx: AgentContext, p: LearnedPatterns): Insight[] {
  const out: Insight[] = [];
  const now = ctx.now;
  const today = dayKey(now);
  const area = ctx.zoneName.replace(/\s*\(.*\)$/, '');

  // ---------------------------------------------------------------- Light going off
  const win = predictOutageWindow(p.power, now);
  const fuelRising = !!p.fuel && p.fuel.recentCount >= 2 && p.fuel.baselineCount >= 2 && p.fuel.changePct >= 5;

  if (win && ctx.zoneState !== 'OFF_GRID' && win.start.getTime() > now.getTime() && win.start.getTime() - now.getTime() <= 8 * HOUR && win.seenDays >= MIN_DAYS_FOR_PREDICTION) {
    const when = partOfDay(win.start, now);
    const range = `${timeLabel(win.start)}–${timeLabel(win.end)}`;
    const soon = win.start.getTime() - now.getTime() <= 2 * HOUR;
    out.push({
      key: `POWER_OUTAGE:${dayKey(win.start)}:${win.start.getHours()}`,
      kind: 'POWER_OUTAGE',
      priority: soon ? 3 : 2,
      confidence: Math.min(0.95, win.probability * Math.min(1, win.seenDays / 7)),
      title: `Light likely off ${range} ${when.en}. Charge your phone and power bank now.`,
      titlePcm: `Light fit go ${range} ${when.pcm}. Charge your phone and power bank now.`,
      why: `${area} had no light between ${timeLabel(win.start)} and ${timeLabel(win.end)} on ${win.offDays} of the last ${win.seenDays} days with reports.`,
      dataUsed: [`${p.power.daysObserved} days of light reports in ${area}`],
      action: { label: 'See light status', tab: 'LIGHT_GEN' },
      notifyAt: iso(new Date(Math.max(now.getTime(), win.start.getTime() - 45 * 60_000))),
      validUntil: iso(win.start)
    });

    // Heavy chores waiting for grid power, and light is on now
    const heavy = ctx.chores.filter(
      (c) => !c.completed && c.requiresHeavyLoad && c.triggerCondition === 'ON_GRID_RESTORED'
    );
    if (ctx.zoneState === 'ON_GRID' && heavy.length) {
      const names = heavy.slice(0, 2).map((c) => c.title.toLowerCase());
      out.push({
        key: `CHORES_BEFORE_OUTAGE:${dayKey(win.start)}:${win.start.getHours()}`,
        kind: 'CHORES_BEFORE_OUTAGE',
        priority: 2,
        confidence: Math.min(0.95, win.probability * Math.min(1, win.seenDays / 7)),
        title: `Light is on now. Do ${heavy.length === 1 ? 'your heavy chore' : `your ${heavy.length} heavy chores`} before ${timeLabel(win.start)}: ${names.join(', ')}.`,
        titlePcm: `Light dey now. Do am before ${timeLabel(win.start)}: ${names.join(', ')}.`,
        why: `Light usually goes at ${timeLabel(win.start)} in ${area}, and these chores need grid power.`,
        dataUsed: ['Your chore list', `${p.power.daysObserved} days of light reports`],
        action: { label: 'Open chores', tab: 'CHORE_QUEUE' },
        // 2 hours ahead leaves time to pump and iron before the light goes
        notifyAt: iso(new Date(Math.max(now.getTime(), win.start.getTime() - 2 * HOUR))),
        validUntil: iso(new Date(win.start.getTime() - 30 * 60_000))
      });
    }
  }

  // ---------------------------------------------------------------- Light coming back
  if (ctx.zoneState === 'OFF_GRID') {
    const back = predictReturnHour(p.power, now);
    if (back !== null) {
      const h = p.power.hours[back];
      out.push({
        key: `POWER_RETURN:${today}:${back}`,
        kind: 'POWER_RETURN',
        priority: 1,
        confidence: Math.min(0.95, (1 - h.pOff) * Math.min(1, h.daysSeen / 7)),
        title: `No light now. It usually comes back around ${hourLabel(back)}.`,
        titlePcm: `Light never come. E dey usually return around ${hourLabel(back)}.`,
        why: `On recent days, ${area} usually had light again by ${hourLabel(back)} (${h.daysSeen} days with reports at that hour).`,
        dataUsed: [`${p.power.daysObserved} days of light reports`],
        action: { label: 'See light status', tab: 'LIGHT_GEN' },
        validUntil: iso(new Date(now.getTime() + 3 * HOUR))
      });
    }
  }

  // ---------------------------------------------------------------- Generator fuel
  const g = p.gen;
  if (g.daysLeft !== null && g.daysLeft <= 3) {
    const left = durationLabel(g.daysLeft);
    const weekNeed = Math.max(0, Math.ceil(g.litresPerDay * 7 - ctx.genLiveFuelLitres));
    const cost = weekNeed * bestFuelPrice(ctx, p);
    const buyEn = weekNeed > 0 ? ` Buy about ${weekNeed}L (${naira(cost)}) for the week${fuelRising ? ', today, before the price rises more' : ''}.` : '';
    const buyPcm = weekNeed > 0 ? ` Buy like ${weekNeed}L (${naira(cost)}) for the week${fuelRising ? ', buy am today' : ''}.` : '';
    out.push({
      key: `GEN_FUEL:${today}`,
      kind: 'GEN_FUEL',
      priority: g.daysLeft <= 1 || fuelRising ? 3 : 2,
      confidence: Math.min(0.95, 0.5 + g.daysOfData * 0.07),
      title: `Gen fuel runs out in ${left.en} at your current use.${buyEn}`,
      titlePcm: `Gen fuel go finish in ${left.pcm} as you dey use am.${buyPcm}`,
      why: `You burn about ${round1(g.litresPerDay)}L a day (last ${g.daysOfData} days of gen use) and have ${round1(ctx.genLiveFuelLitres)}L left.`,
      dataUsed: [`${g.daysOfData} days of generator runs`, 'Tank level'],
      action: { label: 'Open gen tracker', tab: 'LIGHT_GEN' },
      validUntil: iso(endOfDay(now))
    });
  }

  // ---------------------------------------------------------------- Fuel price
  const f = p.fuel;
  if (f && f.recentCount >= 2 && f.baselineCount >= 2 && Math.abs(f.changePct) >= 5) {
    const up = f.changePct > 0;
    const pct = Math.round(Math.abs(f.changePct));
    const cheap = f.cheapest ? ` Cheapest seen: ${naira(f.cheapest.priceNgn)}/L at ${f.cheapest.location}.` : '';
    const cheapPcm = f.cheapest ? ` Cheapest: ${naira(f.cheapest.priceNgn)}/L for ${f.cheapest.location}.` : '';
    out.push({
      key: `FUEL_PRICE:${today}:${up ? 'up' : 'down'}`,
      kind: 'FUEL_PRICE',
      // When the gen-fuel suggestion already says "buy today", this one is background info
      priority: up ? (g.daysLeft !== null && g.daysLeft <= 3 ? 1 : 2) : 1,
      confidence: Math.min(0.95, 0.4 + 0.08 * (f.recentCount + f.baselineCount)),
      title: up
        ? `Fuel price up ${pct}% near you. Buy today if you need it.${cheap}`
        : `Fuel price down ${pct}% near you. No need to rush.${cheap}`,
      titlePcm: up
        ? `Fuel price don go up ${pct}% for your area. If you need am, buy today.${cheapPcm}`
        : `Fuel price don come down ${pct}%. No need to rush.${cheapPcm}`,
      why: `Petrol in ${ctx.stateName} averaged ${naira(f.recentMedian)}/L in the last 2 days vs ${naira(f.baselineMedian)}/L last week (${f.recentCount + f.baselineCount} price reports).`,
      dataUsed: [`${f.recentCount + f.baselineCount} fuel price reports in ${ctx.stateName}`],
      action: { label: 'See fuel prices', tab: 'FUEL_RADAR' },
      validUntil: iso(endOfDay(now))
    });
  }

  // ---------------------------------------------------------------- Your bank is down
  const b = p.bank;
  const myBank = b.primaryInstitutionId
    ? ctx.bankWeather.find((w) => w.institutionId === b.primaryInstitutionId)
    : undefined;
  if (myBank && (myBank.statusAdvisory === 'HIGH_FAILURE_HOLD_ON' || myBank.appTransferSuccessPct < 60)) {
    const name = shortBankName(myBank.institutionName);
    const channels = [
      { en: 'POS card', pcm: 'POS card', pct: myBank.posCardSuccessPct },
      { en: 'USSD', pcm: 'USSD', pct: myBank.ussdSuccessPct }
    ].sort((x, y) => y.pct - x.pct);
    const alt = channels[0].pct >= 75 ? channels[0] : null;
    const otherBank = alt
      ? null
      : ctx.bankWeather
          .filter((w) => w.institutionId !== myBank.institutionId && w.statusAdvisory === 'SMOOTH')
          .sort((x, y) => y.appTransferSuccessPct - x.appTransferSuccessPct)[0];
    const adviceEn = alt
      ? ` Use ${alt.en} instead, it's working (${alt.pct}%).`
      : otherBank
      ? ` Use another account if you have one: ${shortBankName(otherBank.institutionName)} is working (${otherBank.appTransferSuccessPct}%).`
      : ' Hold big transfers for now.';
    const advicePcm = alt
      ? ` Use ${alt.pcm}, e dey go (${alt.pct}%).`
      : otherBank
      ? ` Use another account: ${shortBankName(otherBank.institutionName)} dey work (${otherBank.appTransferSuccessPct}%).`
      : ' Hold big transfer for now.';
    out.push({
      key: `BANK_DOWN:${today}:${myBank.institutionId}`,
      kind: 'BANK_DOWN',
      priority: 3,
      confidence: Math.min(0.95, 0.55 + myBank.reportsLastHour / 50),
      title: `Your ${name} app is failing right now (${myBank.appTransferSuccessPct}% success).${adviceEn}`,
      titlePcm: `${name} app no dey work well now (${myBank.appTransferSuccessPct}%).${advicePcm}`,
      why: `${name} is the bank in ${b.alertsSeen ? `most of your ${b.alertsSeen} recent alerts` : 'your alerts'}, and ${myBank.reportsLastHour} people reported it in the last hour.`,
      dataUsed: ['Your bank alerts (on this phone)', 'Live bank network reports'],
      action: { label: 'See bank network', tab: 'BANK_WEATHER' },
      validUntil: iso(new Date(now.getTime() + 2 * HOUR))
    });
  }

  // ---------------------------------------------------------------- Spending
  const s = p.spending;
  const budget = ctx.settings.weeklyBudgetNgn;
  if (budget && s.weekSpent > 0 && s.weekProjected > budget * 1.05) {
    out.push({
      key: `SPENDING:${today}:budget`,
      kind: 'SPENDING',
      priority: 2,
      confidence: 0.8,
      title: `At this pace you'll spend ${naira(s.weekProjected)} this week, ${naira(s.weekProjected - budget)} over your ${naira(budget)} budget.`,
      titlePcm: `As you dey spend so, this week go reach ${naira(s.weekProjected)}. E pass your ${naira(budget)} budget with ${naira(s.weekProjected - budget)}.`,
      why: `You've spent ${naira(s.weekSpent)} since Monday, from the bank alerts on this phone.`,
      dataUsed: ['Your bank alerts (on this phone)', 'Your weekly budget'],
      action: { label: 'Open money', tab: 'MONEY' },
      validUntil: iso(endOfDay(now))
    });
  } else if (s.daysOfData >= 4 && s.avgDailySpent > 0 && s.todaySpent > s.avgDailySpent * 1.5 && s.todaySpent - s.avgDailySpent > 2000) {
    const x = round1(s.todaySpent / s.avgDailySpent);
    out.push({
      key: `SPENDING:${today}:day`,
      kind: 'SPENDING',
      priority: 1,
      confidence: Math.min(0.9, 0.5 + s.daysOfData * 0.05),
      title: `You've spent ${naira(s.todaySpent)} today, about ${x}× your usual ${naira(s.avgDailySpent)}.`,
      titlePcm: `You don spend ${naira(s.todaySpent)} today. E reach ${x}× wetin you dey spend (${naira(s.avgDailySpent)}).`,
      why: `Your usual is the average of ${s.daysOfData} recent days with bank alerts on this phone.`,
      dataUsed: ['Your bank alerts (on this phone)'],
      action: { label: 'Open money', tab: 'MONEY' },
      validUntil: iso(endOfDay(now))
    });
  }

  if (s.urgentThisWeek >= 3 && s.urgentThisWeek > s.urgentLastWeek) {
    out.push({
      key: `URGENT_2K:${today}:${s.urgentThisWeek}`,
      kind: 'URGENT_2K',
      priority: 1,
      confidence: 0.85,
      title: `${s.urgentThisWeek} "urgent 2k" transfers this week (${naira(s.urgentThisWeekNgn)}). Last week was ${s.urgentLastWeek}.`,
      titlePcm: `You don send ${s.urgentThisWeek} "urgent 2k" this week (${naira(s.urgentThisWeekNgn)}). Last week na ${s.urgentLastWeek}.`,
      why: `${s.urgentThisWeek} small transfers since Monday vs ${s.urgentLastWeek} last week, from the bank alerts on this phone.`,
      dataUsed: ['Your bank alerts (on this phone)'],
      action: { label: 'Open money', tab: 'MONEY' },
      validUntil: iso(endOfDay(now))
    });
  }

  // ---------------------------------------------------------------- Commute fare
  const c = p.commute;
  if (c.route && c.latestFare && c.usualFare && c.latestFare >= c.usualFare * 1.1) {
    out.push({
      key: `COMMUTE:${today}`,
      kind: 'COMMUTE',
      priority: 1,
      confidence: Math.min(0.9, 0.5 + c.reports * 0.08),
      title: `${c.route} fare is ${naira(c.latestFare)} now, up from your usual ${naira(c.usualFare)}. Leave a little more transport money.`,
      titlePcm: `${c.route} fare don reach ${naira(c.latestFare)}, e dey usually be ${naira(c.usualFare)}. Carry extra transport money.`,
      why: `Based on the ${c.reports} fares you reported for this route.`,
      dataUsed: [`${c.reports} of your fare reports`],
      action: { label: 'See fares', tab: 'FUEL_RADAR' },
      validUntil: iso(endOfDay(now))
    });
  }

  return out
    .filter((i) => i.confidence >= 0.5)
    .sort(
      (a, b) =>
        b.priority - a.priority ||
        a.validUntil.localeCompare(b.validUntil) ||
        b.confidence - a.confidence
    );
}
